const puppeteer = require('puppeteer');
const fs = require('fs');
const path = require('path');

async function render() {
  const htmlPath = path.resolve(__dirname, 'poster.html');
  const outPath = path.resolve('/app/output/final_poster.png');

  const browser = await puppeteer.launch({
    args: ['--no-sandbox', '--disable-setuid-sandbox']
  });
  const page = await browser.newPage();

  // A1 aspect ratio, high resolution
  await page.setViewport({ width: 2000, height: 2828, deviceScaleFactor: 1 });

  await page.goto(`file://${htmlPath}`, { waitUntil: 'networkidle0' });

  await page.screenshot({ path: outPath });
  await browser.close();
  console.log(`Poster saved to ${outPath}`);
}

render().catch(console.error);
